CREATE TABLE IF NOT EXISTS parties(id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('STEEL_MILL','RECYCLER','INDIVIDUAL')), region TEXT NOT NULL, eligible INTEGER NOT NULL DEFAULT 1, data_origin TEXT NOT NULL DEFAULT 'SIMULATED');
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, unit TEXT NOT NULL DEFAULT 'ton', data_origin TEXT NOT NULL DEFAULT 'SIMULATED');
CREATE TABLE IF NOT EXISTS inventory(id TEXT PRIMARY KEY, party_id TEXT NOT NULL REFERENCES parties(id), category_id INTEGER NOT NULL REFERENCES categories(id), quantity REAL NOT NULL CHECK(quantity>=0), reserved REAL NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=quantity));
CREATE TABLE IF NOT EXISTS prices(id INTEGER PRIMARY KEY, day TEXT NOT NULL, region TEXT NOT NULL, category_id INTEGER NOT NULL REFERENCES categories(id), price REAL NOT NULL CHECK(price>0), scenario TEXT NOT NULL, data_origin TEXT NOT NULL DEFAULT 'SIMULATED', UNIQUE(day,region,category_id));
CREATE TABLE IF NOT EXISTS offers(id TEXT PRIMARY KEY, party_id TEXT NOT NULL REFERENCES parties(id), category_id INTEGER NOT NULL REFERENCES categories(id), inventory_id TEXT NOT NULL REFERENCES inventory(id), quantity REAL NOT NULL CHECK(quantity>0), price REAL NOT NULL CHECK(price>0), region TEXT NOT NULL, data_origin TEXT NOT NULL DEFAULT 'SIMULATED');
CREATE TABLE IF NOT EXISTS requirements(id TEXT PRIMARY KEY, party_id TEXT NOT NULL REFERENCES parties(id), category_id INTEGER NOT NULL REFERENCES categories(id), quantity REAL NOT NULL CHECK(quantity>0), max_price REAL NOT NULL CHECK(max_price>0), region TEXT NOT NULL, data_origin TEXT NOT NULL DEFAULT 'SIMULATED');
CREATE TABLE IF NOT EXISTS quotas(id TEXT PRIMARY KEY, party_id TEXT NOT NULL REFERENCES parties(id), year INTEGER NOT NULL, limit_amount REAL NOT NULL CHECK(limit_amount=5000000), reserved_amount REAL NOT NULL DEFAULT 0, used_amount REAL NOT NULL DEFAULT 0, UNIQUE(party_id,year));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, offer_id TEXT NOT NULL REFERENCES offers(id), requirement_id TEXT NOT NULL REFERENCES requirements(id), quantity REAL NOT NULL CHECK(quantity>0), unit_price REAL NOT NULL, status TEXT NOT NULL, data_origin TEXT NOT NULL DEFAULT 'SIMULATED');
CREATE TABLE IF NOT EXISTS shipments(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), origin TEXT NOT NULL, destination TEXT NOT NULL, capacity REAL NOT NULL CHECK(capacity>0), cost REAL NOT NULL CHECK(cost>=0), status TEXT NOT NULL, data_origin TEXT NOT NULL DEFAULT 'SIMULATED');
CREATE TABLE IF NOT EXISTS migration_version(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
